func (c *typedDocumentClone) list0(v []types.Expr) []types.Expr {
	c.Step(1)
	if v == nil {
		return nil
	}
	key := rt.DocumentSliceKey{Length: len(v), Capacity: cap(v)}
	if cap(v) > 0 {
		key.First = &v[:1][0]
	}
	if key.First != nil {
		if old, ok := c.Slices[key]; ok {
			return old.([]types.Expr)
		}
	}
	c.Step(uint64(len(v)))
	out := rt.AllocSlice(&c.list0Chunk, len(v))
	if key.First != nil {
		if c.Slices == nil {
			c.Slices = make(map[rt.DocumentSliceKey]any)
		}
		c.Slices[key] = out
	}
	for i, item := range v {
		out[i] = c.toTypeExpr(item)
	}
	return out
}
